#!/bin/bash
# Reproducible AU + VST3 build for SergeAnimalTKB (macOS, universal).
#
# Regenerates the JUCE project from SergeAnimalTKB.dsp, applies the three
# required patches to Faust's generated architecture code, builds Release,
# and installs to the user plug-in folders.
#
# SergeAnimalTKB.dsp itself is generated by gen_dsp.py -- edit that, not the
# .dsp. Only SergeAnimalTKB/SergeAnimalTKB.jucer is hand-maintained here; the
# rest of that folder (FaustPluginProcessor.cpp, Builds/, JuceLibraryCode/) is
# generated and gitignored. NOTE: the .jucer stores absolute JUCE module paths,
# so it will need re-pointing on another machine.
#
# Requires: faust (brew), JUCE 8.0.14 at ~/dev/JUCE, and a Projucer built
# from that same JUCE tree (see PROJUCER below -- the /Applications ones are
# 7.0.5 / 8.0.2 and are too old: JuceHeader.h hard-errors on a version
# mismatch).
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PROJ="$ROOT/SergeAnimalTKB"
JUCE="${JUCE:-$HOME/dev/JUCE}"   # override with JUCE=/path/to/JUCE ./build.sh
PROJUCER="$JUCE/extras/Projucer/Builds/MacOSX/build/Release/Projucer.app/Contents/MacOS/Projucer"

if [ ! -x "$PROJUCER" ]; then
    echo "Building matching Projucer from $JUCE ..."
    xcodebuild -project "$JUCE/extras/Projucer/Builds/MacOSX/Projucer.xcodeproj" \
        -configuration Release -target "Projucer - App" build
fi

# 1. Generate. -jsynth is REQUIRED for a MIDI-playable synth: -nvoices alone
#    only sets IS_SYNTH, it does NOT define JUCE_POLY, so without it MIDI
#    notes never reach the DSP's freq/gate/gain controls.
rm -rf /tmp/sergegen && mkdir -p /tmp/sergegen
cp "$ROOT/SergeAnimalTKB.dsp" /tmp/sergegen/
(cd /tmp/sergegen && faust2juce -jsynth -midi -nvoices 1 \
    -jucemodulesdir "$JUCE/modules" SergeAnimalTKB.dsp)

# Keep our configured .jucer; take only the generated source.
cp /tmp/sergegen/SergeAnimalTKB/FaustPluginProcessor.cpp "$PROJ/"

# 2. Patch A -- JUCE 8 removed juce::Font::getStringWidth (6 sites).
perl -pi -e 's/juce::Font\(\)\.getStringWidth\(/juce::GlyphArrangement::getStringWidthInt(juce::Font(), /g' \
    "$PROJ/FaustPluginProcessor.cpp"
test "$(grep -c 'getStringWidthInt' "$PROJ/FaustPluginProcessor.cpp")" = 6

# 3. Patch B -- Faust's JUCE_POLY path leaves the fFirstCall sample-format /
#    channel-adaptation block referencing fDSP, which only exists in the
#    non-poly branch. Guard it or the build fails with "undeclared fDSP".
python3 - "$PROJ/FaustPluginProcessor.cpp" <<'PY'
import sys
p = sys.argv[1]
s = open(p).read()
old_open = "    if (fFirstCall) {\n        fFirstCall = false;\n"
new_open = "#ifndef JUCE_POLY\n    if (fFirstCall) {\n        fFirstCall = false;\n"
old_close = ("            fDSP = std::make_unique<dsp_adapter>(fDSP.release(), "
             "getTotalNumInputChannels(), getTotalNumOutputChannels(), 16384);\n"
             "        }\n    }\n")
new_close = old_close + "#endif\n"
assert old_open in s and old_close in s, "architecture changed -- re-check patch B"
open(p, 'w').write(s.replace(old_open, new_open, 1).replace(old_close, new_close, 1))
print("patch B applied")
PY

# 3b. Patch C -- off-by-one in uiMenu::reflectZone. The constructor sets
#     defaultitem = getNumItems() (1-based) so "defaultitem - 1" is right there,
#     but reflectZone sets defaultitem = int(i) (already 0-based) and subtracts
#     again: value 28 selects item 27, value 0 selects -1 (blank). Worse, the
#     default sendNotificationAsync fires comboBoxChanged, which writes that
#     wrong selection straight back into the DSP zone -- so the patch-matrix
#     defaults were actually being corrupted, not just mis-drawn.
python3 - "$PROJ/FaustPluginProcessor.cpp" <<'PY'
import sys
p = sys.argv[1]
s = open(p).read()
old = ("                    defaultitem = int(i);\n"
       "                }\n            }\n"
       "            if (defaultitem > -1) {\n"
       "                fComboBox.setSelectedItemIndex(defaultitem - 1);\n"
       "            }")
new = ("                    defaultitem = int(i);\n"
       "                }\n            }\n"
       "            if (defaultitem > -1) {\n"
       "                fComboBox.setSelectedItemIndex(defaultitem, juce::dontSendNotification);\n"
       "            }")
assert s.count(old) == 1, "architecture changed -- re-check patch C"
open(p, 'w').write(s.replace(old, new, 1))
print("patch C applied")
PY

# 3c. Point every JUCE module path at $JUCE. Projucer writes some of these as
#     paths relative to the .jucer (e.g. juce_audio_processors_headless as
#     "../../JUCE/modules"), which silently breaks as soon as the project lives
#     somewhere else -- you get "pluginterfaces/base/funknown.h not found".
python3 - "$PROJ/SergeAnimalTKB.jucer" "$JUCE/modules" <<'PY'
import re, sys
p, mods = sys.argv[1], sys.argv[2]
s = open(p).read()
s2 = re.sub(r'(<MODULEPATH id="[^"]+" path=")[^"]*(")', lambda m: m.group(1) + mods + m.group(2), s)
if s2 != s:
    open(p, 'w').write(s2)
    print("module paths normalised to", mods)
PY

# 4. Resave + build. Note the .jucer sets enablePluginBinaryCopyStep="0" per
#    CONFIGURATION (it is a per-config property, not per-exporter): JUCE's
#    copy step sets DEPLOYMENT_LOCATION=YES + DSTROOT=/, which makes Xcode
#    fail with "Cycle inside a single target". We copy manually below.
cd "$PROJ"
"$PROJUCER" --resave SergeAnimalTKB.jucer --fix-missing-dependencies
for t in "SergeAnimalTKB - VST3" "SergeAnimalTKB - AU"; do
    xcodebuild -project Builds/MacOSX/SergeAnimalTKB.xcodeproj \
        -target "$t" -configuration Release build
done

# 5. Install.
OUT="$PROJ/Builds/MacOSX/build/Release"
mkdir -p "$HOME/Library/Audio/Plug-Ins/Components" "$HOME/Library/Audio/Plug-Ins/VST3"
rm -rf "$HOME/Library/Audio/Plug-Ins/Components/SergeAnimalTKB.component" \
       "$HOME/Library/Audio/Plug-Ins/VST3/SergeAnimalTKB.vst3"
cp -R "$OUT/SergeAnimalTKB.component" "$HOME/Library/Audio/Plug-Ins/Components/"
cp -R "$OUT/SergeAnimalTKB.vst3"      "$HOME/Library/Audio/Plug-Ins/VST3/"

killall -9 AudioComponentRegistrar 2>/dev/null || true
auval -v aumu Satk Rnky | tail -3
